import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BGob8Fzn.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Fix common react-native-universal-sheet problems - native view not found, sheet not appearing, Expo Go crash, pod install issues, styles not changing and web bundler errors.","frontmatter":{"description":"Fix common react-native-universal-sheet problems - native view not found, sheet not appearing, Expo Go crash, pod install issues, styles not changing and web bundler errors.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-universal-sheet/reference/troubleshooting"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-universal-sheet/reference/troubleshooting"}],["meta",{"property":"og:title","content":"Troubleshooting · React Native Universal Sheet"}],["meta",{"property":"og:description","content":"Fix common react-native-universal-sheet problems - native view not found, sheet not appearing, Expo Go crash, pod install issues, styles not changing and web bundler errors."}],["meta",{"name":"twitter:title","content":"Troubleshooting · React Native Universal Sheet"}],["meta",{"name":"twitter:description","content":"Fix common react-native-universal-sheet problems - native view not found, sheet not appearing, Expo Go crash, pod install issues, styles not changing and web bundler errors."}]]},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1794234315000}'),i={name:"reference/troubleshooting.md"};function r(s,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="invariant-violation-requirenativecomponent-nativesheethost-was-not-found" tabindex="-1">&quot;Invariant Violation: requireNativeComponent: &#39;NativeSheetHost&#39; was not found&quot; <a class="header-anchor" href="#invariant-violation-requirenativecomponent-nativesheethost-was-not-found" aria-label="Permalink to &quot;&quot;Invariant Violation: requireNativeComponent: &#39;NativeSheetHost&#39; was not found&quot;&quot;">​</a></h2><p>The native code isn&#39;t in your app binary.</p><ol><li>iOS: <code>cd ios &amp;&amp; pod install</code>.</li><li>Rebuild: <code>npx react-native run-ios</code> / <code>run-android</code>, or <code>npx expo run:ios</code> / <code>run:android</code>.</li><li>Expo: you&#39;re probably in Expo Go. Use a <a href="/react-native-universal-sheet/installation/expo">development build</a>.</li></ol><h2 id="usenativesheet-must-be-used-inside-lt-nativesheetprovider-gt" tabindex="-1">&quot;useNativeSheet() must be used inside &lt;NativeSheetProvider&gt;&quot; <a class="header-anchor" href="#usenativesheet-must-be-used-inside-lt-nativesheetprovider-gt" aria-label="Permalink to &quot;&quot;useNativeSheet() must be used inside &amp;lt;NativeSheetProvider&amp;gt;&quot;&quot;">​</a></h2><p>Add the provider at the root, above the component that calls the hook. Check that it isn&#39;t inside a screen that renders later than the caller.</p><h2 id="present-returns-ok-false" tabindex="-1"><code>present()</code> returns <code>{ok: false}</code> <a class="header-anchor" href="#present-returns-ok-false" aria-label="Permalink to &quot;`present()` returns `{ok: false}`&quot;">​</a></h2><p>Log the reason and look it up in <a href="/react-native-universal-sheet/reference/errors">Error reasons</a>. The most common are <code>duplicate-id</code> (the sheet is already open) and <code>invalid-config</code> (a colour that isn&#39;t 6- or 8-digit hex).</p><h2 id="the-sheet-opens-but-content-is-empty-or-zero-height" tabindex="-1">The sheet opens but content is empty or zero-height <a class="header-anchor" href="#the-sheet-opens-but-content-is-empty-or-zero-height" aria-label="Permalink to &quot;The sheet opens but content is empty or zero-height&quot;">​</a></h2><ul><li>Native: the content wrapper fills the sheet with <code>flex: 1</code>. If your root view has a fixed <code>height: 0</code> or <code>position: &#39;absolute&#39;</code> without size, it won&#39;t show.</li><li>With <code>snapPoints: [&#39;content&#39;]</code>, give your content a measurable height (no <code>flex: 1</code> on the root view).</li></ul><h2 id="a-context-theme-store-i18n-is-missing-inside-the-sheet" tabindex="-1">A context (theme, store, i18n) is missing inside the sheet <a class="header-anchor" href="#a-context-theme-store-i18n-is-missing-inside-the-sheet" aria-label="Permalink to &quot;A context (theme, store, i18n) is missing inside the sheet&quot;">​</a></h2><p>Sheet content is rendered by <code>NativeSheetProvider</code>, not by the screen that opened it. Move your context providers <strong>above</strong> <code>NativeSheetProvider</code>.</p><h2 id="styles-or-variant-don-t-change-while-a-nativesheet-is-open" tabindex="-1"><code>styles</code> or <code>variant</code> don&#39;t change while a <code>NativeSheet</code> is open <a class="header-anchor" href="#styles-or-variant-don-t-change-while-a-nativesheet-is-open" aria-label="Permalink to &quot;`styles` or `variant` don&#39;t change while a `NativeSheet` is open&quot;">​</a></h2><p><code>variant</code>, <code>presentation</code>, <code>behavior</code>, <code>side</code>, <code>sizing</code> and <code>styles</code> are read when the sheet opens. Close and reopen it, or change <code>content</code>/<code>appearance</code>, which update in place.</p><h2 id="sheet-closes-when-i-navigate-on-android" tabindex="-1">Sheet closes when I navigate on Android <a class="header-anchor" href="#sheet-closes-when-i-navigate-on-android" aria-label="Permalink to &quot;Sheet closes when I navigate on Android&quot;">​</a></h2><p>The back press went to the sheet first. That&#39;s expected: the topmost sheet takes the back press. Set <code>enableDrag: false</code> to keep it open (see <a href="/react-native-universal-sheet/features/back-button">Back button</a>).</p><h2 id="ios-snap-points-don-t-match-the-heights-i-asked-for" tabindex="-1">iOS: snap points don&#39;t match the heights I asked for <a class="header-anchor" href="#ios-snap-points-don-t-match-the-heights-i-asked-for" aria-label="Permalink to &quot;iOS: snap points don&#39;t match the heights I asked for&quot;">​</a></h2><p>On iOS 15 only the system medium and large detents exist. Custom heights need iOS 16.</p><h2 id="ios-pod-install-fails-with-a-deployment-target-error" tabindex="-1">iOS: <code>pod install</code> fails with a deployment target error <a class="header-anchor" href="#ios-pod-install-fails-with-a-deployment-target-error" aria-label="Permalink to &quot;iOS: `pod install` fails with a deployment target error&quot;">​</a></h2><p>Set <code>platform :ios, &#39;15.0&#39;</code> (or higher) in your <code>Podfile</code>. Expo users: add the config plugin to <code>app.json</code>.</p><h2 id="android-build-fails-with-minsdkversion-21-cannot-be-smaller-than-version-24" tabindex="-1">Android: build fails with &quot;minSdkVersion 21 cannot be smaller than version 24&quot; <a class="header-anchor" href="#android-build-fails-with-minsdkversion-21-cannot-be-smaller-than-version-24" aria-label="Permalink to &quot;Android: build fails with &quot;minSdkVersion 21 cannot be smaller than version 24&quot;&quot;">​</a></h2><p>Raise <code>minSdkVersion</code> to 24 in <code>android/build.gradle</code> (or <code>expo-build-properties</code>).</p><h2 id="web-unexpected-token-or-cannot-find-module-sheetsurface" tabindex="-1">Web: &quot;Unexpected token&quot; or &quot;Cannot find module &#39;./SheetSurface&#39;&quot; <a class="header-anchor" href="#web-unexpected-token-or-cannot-find-module-sheetsurface" aria-label="Permalink to &quot;Web: &quot;Unexpected token&quot; or &quot;Cannot find module &#39;./SheetSurface&#39;&quot;&quot;">​</a></h2><p>Your bundler isn&#39;t compiling TypeScript from <code>node_modules</code> or isn&#39;t resolving <code>.web.tsx</code>. See the <a href="/react-native-universal-sheet/installation/web">Web setup</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p><a href="https://github.com/SachinMeenaSipl/react-native-universal-sheet/issues" target="_blank" rel="noreferrer">Open an issue</a> with your platform, React Native version, library version and a minimal example.</p>',26)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
